import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Crimson/SeaStar-OSD 2023-04-12 Meeting","description":"","frontmatter":{"title":"Ceph Crimson/SeaStar-OSD 2023-04-12 Meeting","date":"2023-04-12T00:00:00.000Z","updated":"2023-04-12T00:00:00.000Z","tags":["Ceph","Crimson 项目","RBD 测试","系统调试","会议安排"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_SeaStar-OSD_2023-04-12_Meeting.md","filePath":"posts/2023/Ceph_Crimson_SeaStar-OSD_2023-04-12_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Crimson_SeaStar-OSD_2023-04-12_Meeting.md"};function o(n,a,s,h,u,d){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Ceph开发和质量保证（QE）团队成员。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Crimson项目进展</strong></p><ul><li>讨论了将Classic Q Quality Service工作移植到Crimson的计划。</li><li>探讨了LBA优化和parent-child link优化，提出后续改进的可能性。</li></ul></li><li><p><strong>RBD测试结果</strong></p><ul><li>QE团队在RBD测试中发现了五个失败案例，其中两个确认为误报。</li><li>计划进一步调查其余失败案例，并可能提出新的bug报告。</li></ul></li><li><p><strong>系统调试与更新</strong></p><ul><li>更新了医疗系统，并在垂直OST上进行调试，特别是单个和多个OSD的调试。</li></ul></li><li><p><strong>会议安排</strong></p><ul><li>下一周的会议将照常进行，之后可能会切换到新的会议软件。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认将Classic Q Quality Service工作移植到Crimson。</li><li>对RBD测试中的失败案例进行初步分析，并计划进一步讨论和调查。</li><li>确认下一周的会议将继续使用当前的会议软件。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行LBA优化和parent-child link优化的工作。</li><li>QE团队将调查RBD测试中的失败案例，并根据讨论结果决定是否提出新的bug报告。</li><li>调试和更新医疗系统，确保其稳定运行。</li><li>准备切换到新的会议软件，并提前通知参会人员。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到了技术细节，如LBA优化、parent-child link优化等，这些是Ceph存储系统中的关键技术点。</li><li>会议还涉及了RBD（RADOS Block Device）的测试，这是Ceph提供的一种块存储服务。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在确认了后续行动计划和会议安排后结束。</li></ul>',13)])])}const _=e(r,[["render",o]]);export{c as __pageData,_ as default};
